}

.software-page .software-back {
  color: var(--holo-muted);
  font: 600 11px/1 var(--holo-font);
  letter-spacing: 0.3em;
  text-decoration: none;
  text-transform: uppercase;
  transition: color 250ms ease;
}

.software-page .software-back:hover,
.software-page .software-back:focus {
  color: #fff;
  text-decoration: none;
}

/* --- hero: the Earth with the intro beside it ---------------------------- */
.software-hero {
  position: relative;
  height: 100vh;
  height: 100svh;
  min-height: 560px;
}

.software-earth {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
  touch-action: pan-y;
}

.software-earth.is-dragging {
