}

.software-intro {
  position: absolute;
  z-index: 2;
  left: max(32px, calc((100vw - 1280px) / 2 + 32px));
  bottom: 14vh;
  max-width: 400px;
  pointer-events: none;
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 800ms ease, transform 800ms ease;
}

.is-ready .software-intro {
  opacity: 1;
  transform: none;
}

/* small, spaced, coloured labels */
.software-page .software-label {
  margin: 0 0 16px;
  color: var(--holo-light);
  font: 700 11px/1 var(--holo-display);
  letter-spacing: 0.32em;
