/* --- phones ------------------------------------------------------------- */
@media (max-width: 800px) {
  .software-top {
    padding: 20px 16px 0;
  }

  .software-page .software-back {
    font-size: 10px;
    letter-spacing: 0.22em;
  }

  /* the Earth fills the top of the screen; the intro, the motion hint and
