  }

  .software-page .software-lede {
    margin-top: 18px;
  }

  .software-page .software-stats {
    margin-top: 24px;
  }

  .software-page .software-lede {
    font-size: 16px;
  }

  .software-page .software-stats {
    gap: 24px;
  }

  .software-stats dd {
    font-size: 18px;
  }

  .software-block {
    padding: 80px 20px 0;
  }

  .software-hero + .software-block {
    padding-top: 28px;
  }

  .software-heading {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
    margin-bottom: 48px;
  }

  /* long runs of the path between cards, so the scroll draws it out */
  .software-page .xp-list {
    gap: 150px;
  }

  /* the cards stack down the middle, the path a spine running behind them */
  .xp-card,
  .xp-card.is-left,
  .xp-card.is-right {
    width: 100%;
    max-width: 480px;
    align-self: center;
  }

  .xp-meta {
    padding: 16px 8px 4px;
    text-align: center;
  }

  .xp-dates {
    justify-content: center;
  }

  .xp-modal {
    align-items: flex-start;
    padding: 16px 12px;
  }

  .xp-modal-body {
    padding: 22px 20px 24px;
  }

  .xp-modal .xp-modal-title {
    font-size: 26px;
  }

  .software-more {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
    padding-top: 100px;
  }
}

/* short phones (an SE with Safari's bars): drop the stats so the scroll cue still shows */
@media (max-width: 800px) and (max-height: 620px) {
  .software-page .software-stats {
    display: none;
  }

  .software-page .software-title {
    font-size: 34px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .software-intro,
  .software-scroll-cue,
  .xp-card {
    transition: none;
  }

  .software-motion-icon,
  .software-scroll-cue::after,
  .xp-modal,
  .xp-modal-panel {
    animation: none;
