tware-page {\n  --gold: #ffce80;\n  --date: #4fcaf5;\n  min-height: 100vh;\n  background: #010207;\n  color: #ccd4de;\n  font-family: var(--holo-font);\n  overflow-x: hidden;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* --- top bar ------------------------------------------------------------ */\n.software-top {\n  position: absolute;\n  z-index: 5;\n  top: 0;\n  left: 0;\n  right: 0;\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 16px;\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 24px 32px 0;\n  pointer-events: none;\n}\n\n.software-top > * {\n  pointer-events: auto;\n}\n\n.software-page .software-back {\n  color: var(--holo-muted);\n  font: 600 11px/1 var(--holo-font);\n  letter-spacing: 0.3em;\n  text-decoration: none;\n  text-transform: uppercase;\n  transition: color 250ms ease;\n}\n\n.software-page .software-back:hover,\n.software-page .software-back:focus {\n  color: #fff;\n  text-decoration: none;\n}\n\n/* --- hero: the Earth with the intro beside it ---------------------------- */\n.software-hero {\n  position: relative;\n  height: 100vh;\n  height: 100svh;\n  min-height: 560px;\n}\n\n.software-earth {\n  position: absolute;\n  inset: 0;\n  display: block;\n  width: 100%;\n  height: 100%;\n  cursor: grab;\n  touch-action: pan-y;\n}\n\n.software-earth.is-dragging {\n  cursor: grabbing;\n}\n\n.software-intro {\n  position: absolute;\n  z-index: 2;\n  left: max(32px, calc((100vw - 1280px) / 2 + 32px));\n  bottom: 14vh;\n  max-width: 400px;\n  pointer-events: none;\n  opacity: 0;\n  transform: translateY(16px);\n  transition: opacity 800ms ease, transform 800ms ease;\n}\n\n.is-ready .software-intro {\n  opacity: 1;\n  transform: none;\n}\n\n/* small, spaced, coloured labels */\n.software-page .software-label {\n  margin: 0 0 16px;\n  color: var(--holo-light);\n  font: 700 11px/1 var(--holo-display);\n  letter-spacing: 0.32em;\n  text-transform: uppercase;\n}\n\n.software-page .software-title {\n  margin: 0;\n  