   Holo UI: form controls and panels drawn in lines of glowing light, like
   the homepage cube. Shared by sign in and the admin pages.
   --------------------------------------------------------------------- */
.holo-ui {
  --holo-cyan: #00bff3;
  --holo-light: #6ff5ee;
  --holo-line: rgba(111, 245, 238, 0.5);
  --holo-error: #ff6b86;
  --holo-text: #eaf7ff;
  --holo-muted: #788b94;
  --holo-dim: #4e5f76;
  --holo-font: "DINWeb", "Lucida Grande", verdana, sans-serif;
  --holo-display: "Orbitron", "DINWeb", "Lucida Grande", verdana, sans-serif;
}

/* --- panel: dark glass with scan lines and the paintings' HUD brackets -- */
.holo-panel {
  position: relative;
}

.holo-panel-frame {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(111, 245, 238, 0.22);
  border-radius: 6px;
  background: rgba(2, 7, 15, 0.86);
  box-shadow: 0 30px 60px -20px rgba(0, 0, 0, 0.9), 0 0 40px rgba(61, 139, 255, 0.12),
    inset 0 0 30px rgba(0, 191, 243, 0.06);
  pointer-events: none;
}

.holo-panel-frame::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: repeating-linear-gradient(0deg, rgba(111, 245, 238, 0.035) 0 1px, transparent 1px 4px);
}

.holo-corner {
  position: absolute;
  width: 22px;
  height: 22px;
  border: 0 solid rgba(111, 245, 238, 0.7);
  filter: drop-shadow(0 0 4px rgba(111, 245, 238, 0.6));
}

.holo-corner.is-tl {
  top: -12px;
  left: -12px;
  border-top-width: 1px;
  border-left-width: 1px;
}

.holo-corner.is-tr {
  top: -12px;
  right: -12px;
  border-top-width: 1px;
  border-right-width: 1px;
}

.holo-corner.is-bl {
  bottom: -12px;
  left: -12px;
  border-bottom-width: 1px;
  border-left-width: 1px;
}

.holo-corner.is-br {
  bottom: -12px;
  right: -12px;
  border-bottom-width: 1px;
  border-right-width: 1px;
}

.holo-panel-body {
  position: relative;
}

/* --- text: kicker, display title, labels ------------------------------ */
.holo-ui .holo-kicker {
  margin: 0;
  color: var(--holo-cyan);
  font: 600 10px/1 var(--holo-font);
  letter-spacing: 0.4em;
  text-transform: uppercase;
}

.holo-ui .holo-title {
  margin: 0;
  color: #effdff;
  font: 600 26px/1.1 var(--holo-display);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-shadow: 0 0 12px rgba(111, 245, 238, 0.7), 0 0 26px rgba(0, 191, 243, 0.45);
}

.holo-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  min-width: 0;
}

.holo-ui .holo-label {
  color: var(--holo-cyan);
  font: 600 10px/1 var(--holo-font);
  letter-spacing: 0.26em;
  text-transform: uppercase;
}

.holo-ui .holo-error {
  color: var(--holo-error);
  font: 600 10px/1.3 var(--holo-font);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

/* --- inputs: like the cube's squares, just lines of glowing light ------ */
.holo-ui .holo-input {
  display: block;
  width: 100%;
  box-sizing: border-box;
  margin: 0;
  padding: 12px 14px;
  border: 1px solid var(--holo-line);
  border-radius: 4px;
  outline: none;
  background: rgba(4, 12, 24, 0.6);
  box-shadow: 0 0 6px rgba(0, 191, 243, 0.4), inset 0 0 10px rgba(0, 191, 243, 0.14);
  color: var(--holo-text);
  caret-color: var(--holo-light);
  /* 16px stops iOS zooming in on focus */
  font: 500 16px/1.4 var(--holo-font);
  letter-spacing: 0.03em;
  transition: border-color 200ms ease, box-shadow 200ms ease, background 200ms ease;
  -webkit-appearance: none;
  appearance: none;
}

.holo-ui textarea.holo-input {
  min-height: 140px;
  resize: vertical;
}

.holo-ui .holo-input::placeholder {
  color: var(--holo-dim);
}

.holo-ui .holo-input:hover {
  border-color: rgba(111, 245, 238, 0.75);
}

.holo-ui .holo-input:focus,
.holo-ui .holo-input:focus-within {
  border-color: var(--holo-light);
  background: rgba(111, 245, 238, 0.05);
  box-shadow: 0 0 16px rgba(111, 245, 238, 0.7), inset 0 0 16px rgba(111, 245, 238, 0.25);
}

/* keep the browser's autofill from painting the fields yellow */
.holo-ui .holo-input:-webkit-autofill,
.holo-ui .holo-input:-webkit-autofill:hover,
.holo-ui .holo-input:-webkit-autofill:focus {
  -webkit-text-fill-color: var(--holo-text);
  -webkit-box-shadow: 0 0 0 1000px #04101c inset, 0 0 8px rgba(111, 245, 238, 0.5);
  transition: background-color 9999s ease-out 0s;
}

.holo-field.has-error .holo-input {
  border-color: var(--holo-error);
  box-shadow: 0 0 10px rgba(255, 107, 134, 0.5), inset 0 0 10px rgba(255, 107, 134, 0.15);
}

/* --- buttons ------------------------------------------------------------ */
.holo-ui .holo-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  margin: 0;
  padding: 12px 20px;
  overflow: hidden;
  box-sizing: border-box;
  border: 1px solid rgba(111, 245, 238, 0.85);
  border-radius: 4px;
  background: rgba(111, 245, 238, 0.06);
  box-shadow: 0 0 10px rgba(111, 245, 238, 0.55), inset 0 0 14px rgba(111, 245, 238, 0.2);
  color: var(--holo-light);
  cursor: pointer;
  font: 600 12px/1 var(--holo-display);
  letter-spacing: 0.26em;
  text-decoration: none;
  text-transform: uppercase;
  text-shadow: 0 0 8px rgba(111, 245, 238, 0.6);
  white-space: nowrap;
  transition: box-shadow 200ms ease, background 200ms ease, color 200ms ease, border-color 200ms ease;
}

.holo-ui .holo-button:hover,
.holo-ui .holo-button:focus-visible {
  outline: none;
  background: rgba(111, 245, 238, 0.14);
  color: #fff;
  text-decoration: none;
  box-shadow: 0 0 22px rgba(111, 245, 238, 0.9), inset 0 0 26px rgba(111, 245, 238, 0.5);
}

.holo-ui .holo-button:active {
  box-shadow: 0 0 26px rgba(111, 245, 238, 1), inset 0 0 36px rgba(111, 245, 238, 0.7);
}

.holo-ui .holo-button:focus:not(:focus-visible) {
  outline: none;
}

.holo-ui .holo-button:disabled {
  cursor: progress;
}

/* quiet: a line of light that only glows when you reach for it */
.holo-ui .holo-button.is-quiet {
  border-color: rgba(111, 245, 238, 0.3);
  background: transparent;
  box-shadow: none;
  color: var(--holo-muted);
  text-shadow: none;
}

.holo-ui .holo-button.is-quiet:hover,
.holo-ui .holo-button.is-quiet:focus-visible {
  border-color: var(--holo-light);
  color: var(--holo-light);
  box-shadow: 0 0 14px rgba(111, 245, 238, 0.5), inset 0 0 14px rgba(111, 245, 238, 0.2);
}

.holo-ui .holo-button.is-danger {
  border-color: rgba(255, 107, 134, 0.6);
  background: transparent;
  box-shadow: none;
  color: var(--holo-error);
  text-shadow: none;
}

.holo-ui .holo-button.is-danger:hover,
.holo-ui .holo-button.is-danger:focus-visible,
.holo-ui .holo-button.is-danger.is-armed {
  border-color: var(--holo-error);
  background: rgba(255, 107, 134, 0.1);
  color: #fff;
  box-shadow: 0 0 16px rgba(255, 107, 134, 0.6), inset 0 0 14px rgba(255, 107, 134, 0.25);
}

.holo-ui .holo-button.is-small {
  min-height: 34px;
  padding: 8px 12px;
  font-size: 10px;
  letter-spacing: 0.2em;
}

