.holo-ui .holo-button.is-busy::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: -40%;
  width: 40%;
  background: linear-gradient(90deg, transparent, rgba(111, 245, 238, 0.35), transparent);
  animation: holo-sweep 1.1s linear infinite;
}

@keyframes holo-sweep {
  to {
    left: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .holo-ui .holo-button.is-busy::after {
    animation: none;
  }
}
