   Game: a HUD in the site's holo style over the neon world. Readouts in
   HUD boxes, round glass tool buttons, holo panels for the cards.
   --------------------------------------------------------------------- */
html.game-html,
html.game-html body {
  background: #02050b;
}

.game-root {
  /* pinned to the viewport: 100vw/100vh in normal flow overflowed by the
     body margin and the scrollbar width */
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  z-index: 999;
  background: #02050b;
  color: #ccd4de;
  font-family: var(--holo-font);
  user-select: none;
  -webkit-user-select: none;
  --gutter: 24px;
}

.game-root.is-touch {
  --gutter: 14px;
}

.game-canvas {
  width: 100%;
  height: 100%;
}

.game-canvas canvas {
  display: block;
}

.game-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, rgba(2, 5, 11, 0) 50%, rgba(2, 5, 11, 0.7) 100%);
}

/* --- back to the site ---------------------------------------------------- */
.game-root .game-home {
  position: absolute;
  z-index: 6;
  top: calc(var(--gutter) + 2px);
  left: var(--gutter);
  padding: 6px 0;
  color: var(--holo-muted);
  font: 600 11px/1 var(--holo-font);
  letter-spacing: 0.3em;
  text-decoration: none;
  text-transform: uppercase;
  transition: color 250ms ease;
}

.game-root .game-home:hover,
.game-root .game-home:focus-visible {
  color: #fff;
  text-decoration: none;
  outline: none;
}

/* --- readouts: crystals and time --------------------------------------- */
.game-readouts {
  position: absolute;
  z-index: 5;
  top: var(--gutter);
  left: 50%;
  display: flex;
  gap: 12px;
  transform: translateX(-50%);
  pointer-events: none;
}

.game-readout {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 112px;
  padding: 9px 16px 10px;
  border: 1px solid rgba(111, 245, 238, 0.28);
  border-left: 2px solid var(--holo-light);
  border-radius: 4px;
  background: rgba(2, 8, 16, 0.72);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  box-shadow: 0 0 18px rgba(0, 191, 243, 0.12);
}

.game-readout-label {
  color: var(--holo-cyan);
  font: 600 9px/1 var(--holo-font);
  letter-spacing: 0.28em;
  text-transform: uppercase;
}

.game-readout-value {
  color: #effdff;
  font: 700 19px/1 var(--holo-display);
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 10px rgba(111, 245, 238, 0.5);
}

.game-readout-value small {
  color: var(--holo-muted);
  font-size: 12px;
  text-shadow: none;
}

/* --- tools: sound, reset, help ------------------------------------------ */
.game-tools {
  position: absolute;
  z-index: 6;
  top: var(--gutter);
  right: var(--gutter);
  display: flex;
  gap: 8px;
}

.game-root .game-tool {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin: 0;
  padding: 0;
  border: 1px solid rgba(111, 245, 238, 0.35);
  border-radius: 50%;
  background: rgba(2, 8, 16, 0.72);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  color: var(--holo-light);
  cursor: pointer;
  transition: border-color 200ms ease, box-shadow 200ms ease, color 200ms ease;
}

.game-root .game-tool:hover,
.game-root .game-tool:focus-visible,
.game-root .game-tool.is-on {
  border-color: var(--holo-light);
  color: #fff;
  box-shadow: 0 0 14px rgba(111, 245, 238, 0.45);
  outline: none;
}

/* --- speed --------------------------------------------------------------- */
.game-speed {
  position: absolute;
  z-index: 5;
  left: var(--gutter);
  bottom: var(--gutter);
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px 18px 12px 16px;
  border: 1px solid rgba(111, 245, 238, 0.28);
  border-left: 2px solid var(--holo-light);
  border-radius: 4px;
  background: rgba(2, 8, 16, 0.72);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  pointer-events: none;
  transition: box-shadow 200ms ease, border-color 200ms ease;
}

.game-speed-value {
  color: #effdff;
  font: 700 34px/1 var(--holo-display);
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 12px rgba(111, 245, 238, 0.55);
}

.game-speed-unit {
  color: var(--holo-cyan);
  font: 600 9px/1 var(--holo-font);
  letter-spacing: 0.28em;
  text-transform: uppercase;
}

.game-speed.is-boost {
  border-color: var(--holo-light);
  box-shadow: 0 0 26px rgba(111, 245, 238, 0.45), inset 0 0 18px rgba(0, 191, 243, 0.25);
}

/* --- toasts --------------------------------------------------------------- */
.game-toasts {
  position: absolute;
  z-index: 6;
  top: calc(var(--gutter) + 72px);
  left: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  transform: translateX(-50%);
  pointer-events: none;
}

.game-toast {
  padding: 10px 20px;
  border: 1px solid rgba(111, 245, 238, 0.45);
  border-radius: 999px;
  background: rgba(2, 8, 16, 0.82);
  color: #effdff;
  font: 600 12px/1 var(--holo-display);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  white-space: nowrap;
  box-shadow: 0 0 18px rgba(0, 191, 243, 0.25);
  animation: game-toast 2.4s ease forwards;
}

@keyframes game-toast {
  0% {
    opacity: 0;
    transform: translateY(-8px);
  }
  10% {
    opacity: 1;
    transform: none;
  }
  85% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(-6px);
  }
}

/* --- the prompt on a project pad ----------------------------------------- */
.game-root .game-zone {
  position: absolute;
  z-index: 6;
  left: 50%;
  bottom: 34px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 14px 28px;
  border: 1px solid var(--holo-light);
  border-radius: 6px;
  background: rgba(2, 8, 16, 0.86);
  color: #effdff;
  cursor: pointer;
  box-shadow: 0 0 26px rgba(0, 191, 243, 0.35), inset 0 0 18px rgba(0, 191, 243, 0.15);
  transform: translateX(-50%);
  animation: game-rise 300ms ease;
  font-family: inherit;
}

@keyframes game-rise {
  from {
    opacity: 0;
    transform: translate(-50%, 12px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.game-zone-title {
  font: 700 18px/1 var(--holo-display);
  letter-spacing: 0.16em;
  text-shadow: 0 0 10px rgba(111, 245, 238, 0.6);
}

.game-zone-cta {
  color: var(--holo-cyan);
  font: 600 10px/1 var(--holo-font);
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

/* --- cards: intro, help, win ------------------------------------------- */
.game-card {
  position: absolute;
  z-index: 7;
  left: 50%;
  width: min(480px, calc(100% - 2 * var(--gutter) - 24px));
  transform: translateX(-50%);
}

.game-card > .holo-panel-body {
  padding: 24px 28px 22px;
  color: #ccd4de;
  font: 400 15px/1.6 var(--holo-font);
}

.game-card p {
  margin: 10px 0 0;
}

.game-root .game-card .holo-kicker {
  margin: 0;
}

.game-root .game-card-title {
  margin-top: 12px;
  font-size: 24px;
}

.game-hint {
  color: var(--holo-muted);
  font: 600 10px/1.5 var(--holo-font);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.game-intro {
  top: calc(var(--gutter) + 92px);
  animation: game-card-in 500ms ease;
}

@keyframes game-card-in {
  from {
    opacity: 0;
    transform: translate(-50%, -10px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.game-help {
  top: calc(var(--gutter) + 92px);
  cursor: pointer;
}

.game-help ul {
  margin: 10px 0 18px;
  padding-left: 18px;
}

.game-help li {
  margin: 4px 0;
}

.game-help li::marker {
  color: var(--holo-cyan);
}

.game-help b {
  color: #effdff;
  font-family: var(--holo-display);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
}

.game-win-backdrop {
  position: absolute;
  z-index: 8;
  inset: 0;
  background: rgba(1, 3, 8, 0.55);
}

.game-win {
  top: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}

.game-root .game-win-time {
  margin: 16px 0 0;
  color: #fff;
  font: 700 54px/1 var(--holo-display);
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px rgba(111, 245, 238, 0.7), 0 0 36px rgba(0, 191, 243, 0.4);
}

.game-win-best {
  color: var(--holo-cyan);
  font: 600 11px/1 var(--holo-font);
  letter-spacing: 0.26em;
  text-transform: uppercase;
}

.game-win-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 22px;
}

/* --- touch controls: glass keys ------------------------------------------- */
.game-pad {
  position: fixed;
  z-index: 1000;
  display: flex;
  gap: 12px;
}

.game-pad.steer {
  left: calc(env(safe-area-inset-left, 0px) + 16px);
  bottom: calc(env(safe-area-inset-bottom, 0px) + 22px);
}

.game-pad.throttle {
  right: calc(env(safe-area-inset-right, 0px) + 16px);
  bottom: calc(env(safe-area-inset-bottom, 0px) + 22px);
  flex-direction: column;
}

.game-pad.extras {
  right: calc(env(safe-area-inset-right, 0px) + 96px);
  bottom: calc(env(safe-area-inset-bottom, 0px) + 22px);
  flex-direction: column;
  gap: 10px;
}

.game-pad-btn {
  display: grid;
  place-items: center;
  width: 66px;
  height: 66px;
  border: 1px solid rgba(111, 245, 238, 0.4);
  border-radius: 14px;
  background: rgba(2, 8, 16, 0.7);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  color: var(--holo-light);
  cursor: pointer;
  touch-action: none;
  box-shadow: 0 0 14px rgba(0, 191, 243, 0.15), inset 0 0 12px rgba(0, 191, 243, 0.08);
  transition: transform 80ms ease, box-shadow 80ms ease, background 80ms ease;
}

.game-pad-btn.small {
  width: 54px;
  height: 46px;
  border-radius: 10px;
  font: 600 8px/1 var(--holo-font);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.game-pad-btn.is-pressed {
  transform: scale(0.92);
  border-color: var(--holo-light);
  background: rgba(0, 191, 243, 0.22);
  color: #fff;
  box-shadow: 0 0 22px rgba(111, 245, 238, 0.6), inset 0 0 16px rgba(111, 245, 238, 0.35);
}

/* --- phones: the readouts drop under the back link ----------------------- */
@media (max-width: 760px) {
  .game-root .game-home {
    font-size: 10px;
    letter-spacing: 0.22em;
  }

  .game-readouts {
    top: calc(var(--gutter) + 34px);
    left: var(--gutter);
    gap: 8px;
    transform: none;
  }

  .game-readout {
    min-width: 0;
    padding: 7px 12px 8px;
  }

  .game-readout-value {
    font-size: 15px;
  }

  .game-root .game-tool {
    width: 38px;
    height: 38px;
  }

  .game-toasts {
    top: calc(var(--gutter) + 104px);
  }

  .game-toast {
    font-size: 11px;
  }

  .game-root .game-zone {
    bottom: 120px;
  }

  .game-intro,
  .game-help {
    top: calc(var(--gutter) + 104px);
  }

  .game-card > .holo-panel-body {
    padding: 18px 18px 16px;
    font-size: 14px;
  }

  .game-root .game-win-time {
    font-size: 40px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .game-toast,
  .game-root .game-zone,
  .game-intro {
    animation: none;
  }
}
