   Admin pages: the holo UI (components/holo) on the site's black.
   --------------------------------------------------------------------- */
html.admin-html,
body.admin-body {
  background: #000;
}

.admin {
  min-height: 100vh;
  min-height: 100dvh;
  background: linear-gradient(170deg, #03050a 0%, #000 55%, #02050b 100%) fixed;
  color: #ccd4de;
  font-family: var(--holo-font);
  -webkit-font-smoothing: antialiased;
}

/* --- header: home link and the admin nav ------------------------------ */
.admin-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px 28px;
  flex-wrap: wrap;
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 32px;
  box-sizing: border-box;
}

.admin .admin-home {
  color: var(--holo-muted);
  font: 600 11px/1 var(--holo-font);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  text-decoration: none;
  transition: color 250ms ease;
}

.admin .admin-home:hover,
.admin .admin-home:focus {
  color: #fff;
  text-decoration: none;
}

.admin-nav {
  display: flex;
  align-items: center;
  gap: 8px 22px;
  flex-wrap: wrap;
}

.admin .admin-nav-link {
  position: relative;
  padding: 8px 0;
  color: var(--holo-muted);
  font: 600 11px/1 var(--holo-font);
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-decoration: none;
  transition: color 250ms ease;
}

.admin .admin-nav-link:hover,
.admin .admin-nav-link:focus {
  color: #fff;
  text-decoration: none;
}

.admin .admin-nav-link.is-active {
  color: var(--holo-cyan);
  text-shadow: 0 0 12px rgba(0, 191, 243, 0.45);
}

/* a short line of light under the current page */
.admin .admin-nav-link.is-active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0.22em;
  bottom: 0;
  height: 1px;
  background: linear-gradient(90deg, var(--holo-cyan), transparent);
}

/* --- page -------------------------------------------------------------- */
.admin-main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 32px 72px;
  box-sizing: border-box;
}

.admin-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

.admin .admin-title {
  margin-top: 12px;
  overflow-wrap: anywhere;
}

.admin-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 44px;
  align-items: start;
}

.admin-panel .holo-panel-body {
  padding: 26px 28px 22px;
}

.admin-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.admin .admin-panel-title {
  margin: 0;
  color: #effdff;
  font: 600 15px/1 var(--holo-display);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.admin-count {
  margin-left: 10px;
  color: var(--holo-cyan);
  font-size: 12px;
  letter-spacing: 0.12em;
}

.admin .admin-empty {
  margin: 12px 0 6px;
  color: var(--holo-muted);
  font: 400 14px/1.4 var(--holo-font);
}

.admin .admin-message {
  margin: 0 0 20px;
  color: var(--holo-error);
  font: 600 11px/1.4 var(--holo-font);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.admin .admin-message:empty {
  display: none;
}

/* --- lists: one row per post or client --------------------------------- */
.admin .admin-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.admin-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 0;
  border-top: 1px solid rgba(111, 245, 238, 0.1);
}

.admin-row:first-child {
  border-top: 0;
}

.admin-row-main {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.admin .admin-row-title {
  overflow: hidden;
  color: #e8f6ff;
  font: 500 15px/1.3 var(--holo-font);
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: color 200ms ease;
}

.admin .admin-row-title:hover,
.admin .admin-row-title:focus {
  color: var(--holo-light);
  text-decoration: none;
}

.admin-row-date {
  color: var(--holo-dim);
  font: 600 10px/1 var(--holo-font);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.admin-row-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 8px;
}

/* --- forms -------------------------------------------------------------- */
.admin-form-panel {
  max-width: 880px;
}

.admin-form-panel .holo-panel-body {
  padding: 32px 32px 28px;
}

.admin-form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.admin-form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.admin-form-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px 14px;
  padding-top: 4px;
}

.admin-form-actions .admin-message {
  margin: 0;
}

/* client photo with a preview beside it */
.admin-photo {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 132px;
  gap: 20px;
  align-items: end;
}

.admin-photo-preview {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 88px;
  overflow: hidden;
  border: 1px solid rgba(111, 245, 238, 0.25);
  border-radius: 4px;
  background: rgba(4, 12, 24, 0.6);
}

.admin-photo-preview img {
  display: block;
  max-width: 100%;
  max-height: 100%;
}

.admin-photo-preview span {
  color: var(--holo-dim);
  font: 600 9px/1 var(--holo-font);
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

/* --- rich-text editor ---------------------------------------------------- */
.admin .rte {
  display: flex;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
}

.admin .rte.is-invalid {
  border-color: var(--holo-error);
  box-shadow: 0 0 10px rgba(255, 107, 134, 0.5), inset 0 0 10px rgba(255, 107, 134, 0.15);
}

.rte-toolbar {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  padding: 8px 10px;
  border-bottom: 1px solid rgba(111, 245, 238, 0.2);
  background: rgba(3, 10, 20, 0.95);
}

.rte-group {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.admin .rte-tool {
  min-width: 32px;
  height: 30px;
  padding: 0 9px;
  border: 1px solid rgba(111, 245, 238, 0.18);
  border-radius: 3px;
  background: transparent;
  color: var(--holo-muted);
  cursor: pointer;
  font: 600 11px/1 var(--holo-font);
  letter-spacing: 0.06em;
  transition: border-color 150ms ease, color 150ms ease, box-shadow 150ms ease, background 150ms ease;
}

.admin .rte-tool:hover:not(:disabled),
.admin .rte-tool:focus-visible {
  outline: none;
  border-color: var(--holo-light);
  color: #fff;
  box-shadow: 0 0 10px rgba(111, 245, 238, 0.45);
}

.admin .rte-tool.is-on {
  border-color: var(--holo-light);
  background: rgba(111, 245, 238, 0.12);
  color: var(--holo-light);
}

.admin .rte-tool:disabled {
  opacity: 0.3;
  cursor: default;
}

.rte-tool.is-bold {
  font-weight: 800;
}

.rte-tool.is-italic {
  font-style: italic;
}

.rte-tool.is-underline {
  text-decoration: underline;
}

.rte-tool.is-strike {
  text-decoration: line-through;
}

.rte-content,
.admin .rte-source {
  min-height: 320px;
  max-height: 70vh;
  overflow-y: auto;
  padding: 18px 20px;
  box-sizing: border-box;
  outline: none;
}

.rte-content {
  color: #dbe6ef;
  font: 400 16px/1.7 var(--holo-font);
  overflow-wrap: anywhere;
}

.admin .rte-source {
  width: 100%;
  margin: 0;
  border: 0;
  background: transparent;
  color: var(--holo-light);
  font: 400 13px/1.6 "Menlo", "Consolas", monospace;
  resize: vertical;
}

/* the post as it will read: headings, quotes and code on the dark glass */
.rte-content > :first-child {
  margin-top: 0;
}

.rte-content p {
  margin: 0 0 1em;
}

.rte-content h1,
.rte-content h2,
.rte-content h3 {
  margin: 1.2em 0 0.5em;
  color: #fff;
  font-family: var(--holo-font);
  font-weight: 600;
  line-height: 1.3;
}

.rte-content h1,
.rte-content h2 {
  font-size: 22px;
}

.rte-content h3 {
  font-size: 18px;
}

.rte-content a {
  color: var(--holo-light);
}

.rte-content blockquote {
  margin: 0 0 1em;
  padding: 2px 0 2px 16px;
  border-left: 2px solid var(--holo-cyan);
  color: #b9c7d3;
  font-style: italic;
}

.rte-content pre,
.rte-content code {
  font-family: "Menlo", "Consolas", monospace;
  font-size: 13px;
}

.rte-content pre {
  margin: 0 0 1em;
  padding: 12px 14px;
  overflow-x: auto;
  border: 1px solid rgba(111, 245, 238, 0.2);
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.45);
  color: var(--holo-light);
  white-space: pre-wrap;
}

.rte-content ul,
.rte-content ol {
  margin: 0 0 1em;
  padding-left: 1.5em;
}

.rte-content img {
  max-width: 100%;
  height: auto;
}

/* --- phones -------------------------------------------------------------- */
@media (max-width: 900px) {
  .admin-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 700px) {
  .admin-header {
    padding: 20px 20px 8px;
  }

  .admin-nav {
    width: 100%;
    gap: 6px 18px;
  }

  .admin-main {
    padding: 20px 16px 56px;
  }

  .admin-heading {
    margin-bottom: 30px;
  }

  .admin .admin-title {
    font-size: 21px;
  }

  .admin-panel .holo-panel-body,
  .admin-form-panel .holo-panel-body {
    padding: 22px 18px 18px;
  }

  .admin-form-row,
  .admin-photo {
    grid-template-columns: minmax(0, 1fr);
  }

  .admin-photo-preview {
    width: 132px;
  }

  /* rows: title over its buttons */
  .admin-row {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
  }

  .admin .admin-row-title {
    white-space: normal;
  }

  .rte-content,
  .admin .rte-source {
    min-height: 240px;
    padding: 14px;
  }

  /* the panels' brackets sit closer, clear of the screen's edges */
  .admin .holo-corner.is-tl,
  .admin .holo-corner.is-tr {
    top: -9px;
  }

  .admin .holo-corner.is-bl,
  .admin .holo-corner.is-br {
    bottom: -9px;
  }

  .admin .holo-corner.is-tl,
  .admin .holo-corner.is-bl {
    left: -9px;
  }

  .admin .holo-corner.is-tr,
  .admin .holo-corner.is-br {
    right: -9px;
  }
}
