___CSS_LOADER_EXPORT___.push([module.id, `.ui-toggle {
  position: fixed;
  z-index: 1000;
  right: 28px;
  bottom: 26px;
  bottom: calc(26px + env(safe-area-inset-bottom, 0px));
  display: flex;
  align-items: center;
  gap: 12px;
  font: 600 10px/1 "DINWeb", "Lucida Grande", verdana, sans-serif;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  -webkit-font-smoothing: antialiased;
}

.ui-toggle-label {
  color: #788b94;
}

.ui-toggle-switch {
  position: relative;
  display: flex;
  padding: 3px;
  border: 1px solid rgba(111, 245, 238, 0.35);
  border-radius: 999px;
  background: rgba(3, 10, 20, 0.75);
}

.ui-toggle-thumb {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 3px;
  width: calc(50% - 3px);
  border-radius: 999px;
  background: rgba(111, 245, 238, 0.14);
  box-shadow: 0 0 0 1px rgba(111, 245, 238, 0.6), 0 0 14px rgba(111, 245, 238, 0.35);
  transition: transform 300ms cubic-bezier(0.5, 0, 0.2, 1);
}

.ui-toggle.is-v2 .ui-toggle-thumb {
  transform: translateX(100%);
}

.ui-toggle .ui-toggle-option {
  position: relative;
  min-width: 34px;
  padding: 7px 10px;
  color: #788b94;
  text-align: center;
  text-decoration: none;
  letter-spacing: 0.12em;
  transition: color 250ms ease;
}

.ui-toggle .ui-toggle-option:hover,
.ui-toggle .ui-toggle-option:focus {
  color: #fff;
  text-decoration: none;
}

.ui-toggle .ui-toggle-option.is-active {
  color: #6ff5ee;
}

.ui-toggle .ui-toggle-option:focus:not(:focus-visible) {
  outline: none;
}

@media (max-width: 700px) {
  .ui-toggle {
    right: 16px;
    bottom: 16px;
    bottom: calc(16px + env(safe-area-inset-bottom, 0px));
    gap: 8px;
  }
}
