    text-shadow: none;
  }

  .chart-channel-cta-word {
    display: inline;
  }

  .journal-log {
    padding: 12px 0 8px;
  }

  .journal-page .journal-entry {
    grid-template-columns: 52px minmax(0, 1fr);
    gap: 6px 14px;
    padding: 14px;
  }

  .journal-entry-id {
    grid-row: span 2;
  }

  .journal-entry-id strong {
    font-size: 18px;
  }

  .journal-entry-title {
    font-size: 16px;
  }

  .journal-entry-sub {
    font-size: 13px;
  }

  .journal-entry-date {
    grid-column: 2;
    font-size: 11px;
  }

  .journal-entry-go {
    display: none;
  }
}

/* --- start: the globe assembles out of a point (Globe.js), then the
   leader lines draw, the callouts and panels come in, the corner readouts
   power up and the log rises ------------------------------------------------ */
.journal-top {
  animation: journal-fade 600ms ease-out both;
}

@keyframes journal-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.journal-page .chart-channel {
  animation: chart-extend 420ms cubic-bezier(0.2, 0.8, 0.2, 1) 1550ms both;
}

.journal-page .chart-channel.is-left {
  transform-origin: 100% 50%;
}

.journal-page .chart-channel.is-right {
  transform-origin: 0 50%;
}



.chart-channel-slot.is-axis-1 .chart-channel {
  animation-delay: 1650ms;
}

.chart-channel-slot.is-axis-2 .chart-channel {
  animation-delay: 1750ms;
}

@keyframes chart-extend {
  from {
    opacity: 0;
    scale: 0 1;
  }
  to {
    opacity: 1;
    scale: 1 1;
  }
}

.chart-panel,
.chart-readout {
  animation: journal-rise 500ms ease-out 1450ms both;
}

.chart-gauge {
  animation-delay: 1700ms;
}

/* the corner readouts power up */
.journal-hud-bar {
  animation: journal-bar-in 400ms ease-out calc(1900ms + var(--hud) * 120ms) both;
}

.journal-hud-box {
  animation: journal-hud-in 600ms steps(1, end) calc(2000ms + var(--hud) * 120ms) both, journal-hud-open 450ms ease-out calc(2000ms + var(--hud) * 120ms) both;
}

.journal-hud.is-tl {
  --hud: 0;
}

.journal-hud.is-tr {
  --hud: 1;
}

.journal-hud.is-bl {
  --hud: 2;
}

.journal-hud.is-br {
  --hud: 3;
}

@keyframes journal-bar-in {
  from {
    opacity: 0;
    scale: 1 0;
  }
  to {
    opacity: 0.8;
    scale: 1 1;
  }
}

@keyframes journal-hud-open {
  from {
    clip-path: inset(0 50% 0 50%);
  }
  to {
    clip-path: inset(0 0 0 0);
  }
}

@keyframes journal-hud-in {
  0% {
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  35% {
    opacity: 0.3;
  }
  50%,
  100% {
    opacity: 1;
  }
}

/* the log comes in beneath */
.journal-log-title {
  animation: journal-rise 500ms ease-out 2200ms both;
}

.journal-log-list li {
  animation: journal-rise 500ms ease-out calc(2300ms + var(--i, 0) * 70ms) both;
}

@keyframes journal-rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* --- leaving: the opening in reverse; the log sinks, the readouts power
   down, the callouts retract, the lines withdraw and the globe collapses
   into a point (Globe.js); the link is followed as it goes (LEAVE_MS in
   Journal.js) ----------------------------------------------------------------- */
.is-leaving .journal-log-list li {
  animation: journal-sink 320ms ease-in calc(var(--i, 0) * 25ms) both;
}

.is-leaving .journal-log-title,
.is-leaving .journal-top {
  animation: journal-sink 320ms ease-in both;
}

@keyframes journal-sink {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: translateY(14px);
  }
}

.is-leaving .journal-hud-box {
  animation: journal-hud-shut 300ms ease-in calc(120ms + var(--hud) * 50ms) both;
}

.is-leaving .journal-hud-bar {
  animation: journal-bar-out 260ms ease-in calc(260ms + var(--hud) * 50ms) both;
}

@keyframes journal-hud-shut {
  0% {
    opacity: 1;
    clip-path: inset(0 0 0 0);
  }
  30% {
    opacity: 0.3;
  }
  45% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    clip-path: inset(0 50% 0 50%);
  }
}

@keyframes journal-bar-out {
  from {
    opacity: 0.8;
    scale: 1 1;
  }
  to {
    opacity: 0;
    scale: 1 0;
  }
}

.is-leaving .chart-panel,
.is-leaving .chart-readout {
  animation: journal-sink 300ms ease-in 200ms both;
}

.is-leaving .journal-page .chart-channel,
.journal-page.is-leaving .chart-channel {
  animation: chart-retract 300ms cubic-bezier(0.6, 0, 0.8, 0.2) 250ms both;
}

@keyframes chart-retract {
  from {
    opacity: 1;
    scale: 1 1;
  }
  to {
    opacity: 0;
    scale: 0 1;
  }
}

.is-leaving {
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  .journal-top,
  .journal-page .chart-channel,
  .chart-channel-marker,
  .chart-panel,
  .chart-readout,
  .chart-gauge-scan,
  .journal-hud-bar,
  .journal-hud-box,
  .journal-log-title,
  .journal-log-list li {
    animation: none;
  }
}
